# region imports
from AlgorithmImports import *
import math
# endregion


# ---------------------------------------------------------------------------
# Strategy system
#
#   One template, 2 slots, no gate -> both slots run independently in parallel.
#
#   Slot 1 / Strategy A (SPY) : buy 40% of portfolio value when SPY's close
#                               crosses above its SMA; liquidate the lot when
#                               the close crosses back below the SMA.
#   Slot 2 / Strategy B (AAPL): buy a $20,000 clip after 3 consecutive red
#                               days (only if >= $20,000 cash is available);
#                               liquidate the lot when RSI(14) is above 60.
#
#   The rule text specifies "its simple moving average" without a length, so
#   the conventional 20-day SMA is used (single constant below).
# ---------------------------------------------------------------------------

SMA_PERIOD = 20   # Strategy A trend filter length
RSI_PERIOD = 14   # Strategy B exit oscillator length (Wilder's smoothing)


class TickerState:
    """Continuously maintained market state for one ticker.

    Everything here is advanced from raw data on every bar the ticker prints,
    independently of whether any strategy is currently allowed to trade.
    """

    def __init__(self, symbol, sma_period=None, rsi_period=None):
        self.symbol = symbol
        self.close = None
        self.prev_close = None
        self.red_streak = 0

        self.sma = SimpleMovingAverage(sma_period) if sma_period else None
        self.sma_value = None
        self.prev_sma_value = None

        self.rsi = (RelativeStrengthIndex(rsi_period, MovingAverageType.WILDERS)
                    if rsi_period else None)
        self.rsi_value = None

    def update(self, bar):
        self.prev_close = self.close
        self.close = bar.close

        # A red day is a close strictly below the previous close; the streak
        # value on any bar is the number of consecutive red days ending today.
        if self.prev_close is not None and self.close < self.prev_close:
            self.red_streak += 1
        else:
            self.red_streak = 0

        if self.sma is not None:
            self.prev_sma_value = self.sma_value
            self.sma.update(bar.end_time, bar.close)
            self.sma_value = self.sma.current.value if self.sma.is_ready else None

        if self.rsi is not None:
            self.rsi.update(bar.end_time, bar.close)
            self.rsi_value = self.rsi.current.value if self.rsi.is_ready else None

    def close_crosses_above_sma(self):
        """Yesterday close <= yesterday SMA and today close > today SMA."""
        if self.prev_close is None or self.prev_sma_value is None or self.sma_value is None:
            return False
        return self.prev_close <= self.prev_sma_value and self.close > self.sma_value

    def close_crosses_below_sma(self):
        """Yesterday close >= yesterday SMA and today close < today SMA."""
        if self.prev_close is None or self.prev_sma_value is None or self.sma_value is None:
            return False
        return self.prev_close >= self.prev_sma_value and self.close < self.sma_value


class Lot:
    """A single strategy's private inventory in one ticker.

    A strategy may only ever sell shares this lot bought, so lot size is
    tracked from actual fills rather than from intent.
    """

    def __init__(self, algorithm, owner_name, symbol):
        self.algorithm = algorithm
        self.owner_name = owner_name
        self.symbol = symbol
        self.quantity = 0
        self.pending = 0

    @property
    def is_open(self):
        return self.quantity > 0

    @property
    def is_busy(self):
        """True while an order of this lot has not reached a terminal state."""
        return self.pending > 0

    def buy(self, shares):
        shares = int(shares)
        if shares <= 0:
            return
        self._submit(shares)

    def sell(self, shares):
        shares = int(min(int(shares), self.quantity))
        if shares <= 0:
            return
        self._submit(-shares)

    def liquidate(self):
        self.sell(self.quantity)

    def _submit(self, signed_quantity):
        ticket = self.algorithm.market_order(self.symbol, signed_quantity, tag=self.owner_name)
        if ticket is None:
            return
        self.algorithm.register_lot_order(ticket.order_id, self)
        self.pending += 1

    def on_order_event(self, order_event):
        if order_event.status in (OrderStatus.FILLED, OrderStatus.PARTIALLY_FILLED):
            self.quantity += int(order_event.fill_quantity)
            if self.quantity < 0:
                self.quantity = 0
        if order_event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
            self.pending = max(0, self.pending - 1)


class Strategy:
    """Base slot occupant: one buy reason, one sell reason, one private lot."""

    def __init__(self, algorithm, name, state):
        self.algorithm = algorithm
        self.name = name
        self.state = state
        self.lot = Lot(algorithm, name, state.symbol)

    def is_ready(self):
        return True

    def evaluate_sell(self):
        # The sell reason is only consulted while the lot is non-empty.
        if not self.is_ready() or self.lot.is_busy or not self.lot.is_open:
            return
        if self.should_sell():
            self.do_sell()

    def evaluate_buy(self):
        # The buy reason is only consulted while the lot is empty.
        if not self.is_ready() or self.lot.is_busy or self.lot.is_open:
            return
        if self.should_buy():
            self.do_buy()

    def should_buy(self):
        raise NotImplementedError

    def do_buy(self):
        raise NotImplementedError

    def should_sell(self):
        raise NotImplementedError

    def do_sell(self):
        raise NotImplementedError


class StrategyA(Strategy):
    """Slot 1 - SPY close/SMA crossover, sized to a fixed share of the portfolio."""

    ALLOCATION = 0.40

    def is_ready(self):
        st = self.state
        return st.sma is not None and st.sma.is_ready and st.prev_sma_value is not None

    def should_buy(self):
        return self.state.close_crosses_above_sma()

    def do_buy(self):
        price = self.state.close
        if price is None or price <= 0:
            return
        target_value = self.ALLOCATION * self.algorithm.portfolio.total_portfolio_value
        self.lot.buy(math.floor(target_value / price))

    def should_sell(self):
        return self.state.close_crosses_below_sma()

    def do_sell(self):
        self.lot.liquidate()


class StrategyB(Strategy):
    """Slot 2 - AAPL fixed-dollar dip buy, exited on an RSI(14) reading above 60."""

    RED_DAYS_REQUIRED = 3
    CASH_PER_TRADE = 20000.0
    RSI_EXIT_LEVEL = 60.0

    def is_ready(self):
        st = self.state
        return st.rsi is not None and st.rsi.is_ready

    def should_buy(self):
        return self.state.red_streak >= self.RED_DAYS_REQUIRED

    def do_buy(self):
        # Not enough cash -> do nothing at all this bar; the reason may fire again.
        if self.algorithm.portfolio.cash < self.CASH_PER_TRADE:
            return
        price = self.state.close
        if price is None or price <= 0:
            return
        self.lot.buy(math.floor(self.CASH_PER_TRADE / price))

    def should_sell(self):
        return self.state.rsi_value is not None and self.state.rsi_value > self.RSI_EXIT_LEVEL

    def do_sell(self):
        self.lot.liquidate()


class ParallelTemplate:
    """Ungated template: every slot acts on every bar, sells before buys."""

    def __init__(self, slots):
        self.slots = list(slots)

    def on_bar(self):
        for slot in self.slots:
            slot.evaluate_sell()
        for slot in self.slots:
            slot.evaluate_buy()


class ParallelTemplateAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = []
        self.states = {}
        symbol_by_ticker = {}

        for ticker in self.tickers:
            equity = self.add_equity(ticker, Resolution.DAILY)
            equity.set_data_normalization_mode(DataNormalizationMode.ADJUSTED)
            symbol = equity.symbol
            self.symbols.append(symbol)
            symbol_by_ticker[ticker] = symbol
            self.states[symbol] = TickerState(symbol)

        # Only the traded tickers need derived indicators.
        spy = symbol_by_ticker["SPY"]
        aapl = symbol_by_ticker["AAPL"]
        self.states[spy] = TickerState(spy, sma_period=SMA_PERIOD)
        self.states[aapl] = TickerState(aapl, rsi_period=RSI_PERIOD)

        self._lot_by_order_id = {}

        self._template = ParallelTemplate([
            StrategyA(self, "Strategy A", self.states[spy]),
            StrategyB(self, "Strategy B", self.states[aapl]),
        ])

        # Fully form every indicator / rolling window before any rule can trade.
        self.set_warm_up(max(SMA_PERIOD, RSI_PERIOD) + 26, Resolution.DAILY)

    def register_lot_order(self, order_id, lot):
        self._lot_by_order_id[order_id] = lot

    def on_data(self, data: Slice):
        # 1) Advance market state continuously for every ticker that printed a bar.
        complete_day = True
        for symbol in self.symbols:
            bar = self._bar_for(data, symbol)
            if bar is None:
                complete_day = False
                continue
            self.states[symbol].update(bar)

        # 2) A missing bar on ANY subscribed ticker suspends all rule evaluation.
        if not complete_day or self.is_warming_up:
            return

        # 3) Ungated template: run both slots, sells before buys.
        self._template.on_bar()

    def _bar_for(self, data, symbol):
        if data is None or data.bars is None or not data.bars.contains_key(symbol):
            return None
        bar = data.bars[symbol]
        if bar is None or bar.close <= 0:
            return None
        return bar

    def on_order_event(self, order_event):
        lot = self._lot_by_order_id.get(order_event.order_id)
        if lot is None:
            return
        lot.on_order_event(order_event)
        if order_event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
            self._lot_by_order_id.pop(order_event.order_id, None)

