# region imports
from AlgorithmImports import *
import math
# endregion


# ----------------------------------------------------------------------------------
# Fixed configuration
# ----------------------------------------------------------------------------------
TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

# The spec says "its simple moving average" without giving a length; 20 daily bars is
# the length used here (single place to change it).
SMA_PERIOD = 20

RSI_PERIOD = 14
RSI_SELL_LEVEL = 60.0            # "RSI closes above 60" -> a LEVEL test, not a cross
RED_DAYS_REQUIRED = 3
STRATEGY_A_ALLOCATION = 0.40     # invest 40% of total portfolio value
STRATEGY_B_CASH_CHUNK = 20000.0  # buy $20,000 if at least $20,000 cash is available

# SMA cross needs the SMA of the *previous* bar too -> SMA_PERIOD + 1 bars minimum.
WARMUP_BARS = SMA_PERIOD + 2


# ----------------------------------------------------------------------------------
# Per-symbol market state
#
# Updated from every bar the symbol prints, unconditionally: market-state quantities
# (streaks, indicator values) are always computed from data continuously, independent
# of whether rules are allowed to be evaluated on that day.
# ----------------------------------------------------------------------------------
class MarketState:

    def __init__(self, symbol):
        self.symbol = symbol
        self.bars_seen = 0

        self.close = None          # today's close
        self.prev_close = None     # yesterday's close

        self.red_streak = 0        # consecutive closes strictly below the previous close
        self.green_streak = 0      # consecutive closes strictly above the previous close

        self.sma = SimpleMovingAverage(f"{symbol.value}_SMA_{SMA_PERIOD}", SMA_PERIOD)
        self.sma_value = None      # today's SMA
        self.prev_sma = None       # yesterday's SMA

        self.rsi = RelativeStrengthIndex(f"{symbol.value}_RSI_{RSI_PERIOD}",
                                         RSI_PERIOD, MovingAverageType.WILDERS)
        self.rsi_value = None
        self.prev_rsi = None

    def update(self, bar):
        price = float(bar.close)

        self.prev_close = self.close
        self.close = price

        # Red/green streaks: strictly below / strictly above the PREVIOUS close.
        if self.prev_close is not None:
            if price < self.prev_close:
                self.red_streak += 1
                self.green_streak = 0
            elif price > self.prev_close:
                self.green_streak += 1
                self.red_streak = 0
            else:
                self.red_streak = 0
                self.green_streak = 0

        # Roll indicator values forward before updating so both "yesterday" and
        # "today" values are available for cross tests.
        self.prev_sma = self.sma_value
        self.sma.update(bar.end_time, price)
        self.sma_value = float(self.sma.current.value) if self.sma.is_ready else None

        self.prev_rsi = self.rsi_value
        self.rsi.update(bar.end_time, price)
        self.rsi_value = float(self.rsi.current.value) if self.rsi.is_ready else None

        self.bars_seen += 1

    # --- readiness ---------------------------------------------------------------
    @property
    def sma_cross_ready(self):
        return (self.prev_close is not None
                and self.prev_sma is not None
                and self.sma_value is not None)

    @property
    def rsi_ready(self):
        return self.rsi_value is not None

    @property
    def red_streak_ready(self):
        return self.bars_seen >= RED_DAYS_REQUIRED + 1

    # --- rule primitives ---------------------------------------------------------
    def close_crossed_above_sma(self):
        """Yesterday close <= yesterday SMA AND today close > today SMA."""
        if not self.sma_cross_ready:
            return False
        return self.prev_close <= self.prev_sma and self.close > self.sma_value

    def close_crossed_below_sma(self):
        """Yesterday close >= yesterday SMA AND today close < today SMA."""
        if not self.sma_cross_ready:
            return False
        return self.prev_close >= self.prev_sma and self.close < self.sma_value

    def red_for(self, n):
        """True on any day completing n or more consecutive red days."""
        return self.red_streak_ready and self.red_streak >= n


# ----------------------------------------------------------------------------------
# Strategy base: owns a private lot in its trade ticker.
# It sells only shares it bought; the buy reason is evaluated only while the lot is
# empty, the sell reason only while it is non-empty; sells are evaluated before buys.
# ----------------------------------------------------------------------------------
class Strategy:

    def __init__(self, name, symbol):
        self.name = name
        self.symbol = symbol
        self.shares = 0

    @property
    def is_empty(self):
        return self.shares == 0

    # --- order plumbing ----------------------------------------------------------
    def _buy(self, algo, quantity):
        quantity = int(quantity)
        if quantity <= 0:
            return
        ticket = algo.market_order(self.symbol, quantity)
        self.shares += quantity
        algo.track_lot_order(ticket, self, quantity)
        algo.trade_log(f"{self.name} BUY {quantity} {self.symbol.value} -> lot {self.shares}")

