RED_DAYS_REQUIRED = 3
STRATEGY_A_ALLOCATION = 0.40     # invest 40% of total portfolio value
STRATEGY_B_CASH_CHUNK = 20000.0  # buy $20,000 if at least $20,000 cash is available

