        ])

    # ------------------------------------------------------------------ data
    def on_data(self, data: Slice):
        bars = {symbol: self._get_bar(data, symbol) for symbol in self.symbols}

        # 1) market state always advances on whatever data arrived
        for symbol, bar in bars.items():
