# region imports
from AlgorithmImports import *
# endregion


class MarketState:
    """
    Per-symbol market facts, recomputed from every bar the symbol prints.
    Market state is *never* paused by templates/gates - only rule evaluation is.
    """

    def __init__(self):
        self.close = None        # today's close
        self.prev_close = None   # yesterday's close
        self.red_streak = 0      # number of consecutive red days completed as of today

    def update(self, bar):
        close = bar.close
        if self.close is not None:
            self.prev_close = self.close
            # "red day" == close strictly below the previous day's close
            if close < self.prev_close:
                self.red_streak += 1
            else:
                self.red_streak = 0
        self.close = close

    @property
    def is_formed(self):
        return self.close is not None and self.prev_close is not None


class Strategy:
    """
    A single slot. Owns a private lot of shares in its trade ticker:
      - it only ever sells shares it bought,
      - its buy reason is evaluated only while the lot is empty,
      - its sell reason is evaluated only while the lot is non-empty.
    """

    def __init__(self, algorithm, name, symbol):
        self.algorithm = algorithm
        self.name = name
        self.symbol = symbol
        self.shares = 0

    @property
    def is_open(self):
        return self.shares > 0

    # --- rule hooks -------------------------------------------------------
    def buy_signal(self):
        raise NotImplementedError

    def sell_signal(self):
        raise NotImplementedError

    def buy(self):
        raise NotImplementedError

    def sell(self):
        self.liquidate_lot("sell details: liquidate entire lot")

    # --- driving ----------------------------------------------------------
    def try_sell(self):
        if self.is_open and self.sell_signal():
            self.sell()

    def try_buy(self):
        if not self.is_open and self.buy_signal():
            self.buy()

    # --- lot plumbing -----------------------------------------------------
    def liquidate_lot(self, tag):
        if self.shares > 0:
            self.submit(-self.shares, tag)

    def submit(self, quantity, tag):
        if quantity == 0:
            return
        ticket = self.algorithm.market_order(self.symbol, quantity, tag=f"{self.name} | {tag}")
        # Book the lot optimistically so a reason cannot fire twice while the
        # order is in flight; on_order_event reconciles against the real fill.
        self.shares += quantity
        self.algorithm.register_lot_order(self, ticket, quantity)


class SpyMovingAverageStrategy(Strategy):
    """
    Slot 1 - Strategy A (SPY).
      buy : SPY close crosses above its simple moving average
      size: invest 40% of total portfolio value
      sell: SPY close crosses below its simple moving average -> liquidate lot
    """

    def __init__(self, algorithm, symbol, allocation):
        super().__init__(algorithm, "Strategy A (SPY/SMA)", symbol)
        self.allocation = allocation

    def buy_signal(self):
        return self.algorithm.spy_crossed_above_sma

    def sell_signal(self):
        return self.algorithm.spy_crossed_below_sma

    def buy(self):
        price = self.algorithm.state[self.symbol].close
        target_value = self.algorithm.portfolio.total_portfolio_value * self.allocation
        quantity = int(target_value // price)
        if quantity > 0:
            self.submit(quantity, f"buy details: invest {self.allocation:.0%} of portfolio")


class AaplRedStreakStrategy(Strategy):
    """
    Slot 2 - Strategy B (AAPL).
      buy : AAPL red for 3 consecutive days
      size: $20,000 worth if at least $20,000 cash is available, else do nothing
      sell: 14-day RSI above 60 -> liquidate lot
    """

    def __init__(self, algorithm, symbol, streak_target, cash_per_buy, rsi_level):
        super().__init__(algorithm, "Strategy B (AAPL/RSI)", symbol)
        self.streak_target = streak_target
        self.cash_per_buy = cash_per_buy
        self.rsi_level = rsi_level

    def buy_signal(self):
        # satisfied on any day completing streak_target or more consecutive red days
        return self.algorithm.state[self.symbol].red_streak >= self.streak_target

    def sell_signal(self):
        # a level test, not a cross
        return self.algorithm.aapl_rsi.current.value > self.rsi_level

    def buy(self):
        if self.algorithm.portfolio.cash < self.cash_per_buy:
            return  # not enough cash -> do nothing this bar, stay flat
        price = self.algorithm.state[self.symbol].close
        quantity = int(self.cash_per_buy // price)
        if quantity > 0:
            self.submit(quantity, f"buy details: buy ${self.cash_per_buy:,.0f} if available")


class ParallelTemplate:
    """One template, N slots, no gate. Slots run independently in parallel."""

    def __init__(self, name, slots):
        self.name = name
        self.slots = slots

    def on_bar(self):
        # on any bar, evaluate sells before buys
        for slot in self.slots:
            slot.try_sell()
        for slot in self.slots:
            slot.try_buy()


