    def evaluate_sell(self):
        if not self.can_sell():
            return
        rsi = self.algorithm.aapl_rsi
        if rsi.IsReady and float(rsi.Current.Value) > B_RSI_EXIT_LEVEL:
            self.liquidate_lot("B sell: AAPL RSI({0}) closed above {1}".format(RSI_PERIOD, int(B_RSI_EXIT_LEVEL)))

    def evaluate_buy(self):
        if not self.can_buy():
            return

        algo = self.algorithm
        state = algo.states[self.symbol]
        if state.red_streak < RED_DAYS_REQUIRED:
            return

        # Buy detail: only act if at least $20,000 of cash is available, else do nothing.
        if float(algo.Portfolio.Cash) < B_ORDER_CASH:
            return

        price = state.close
        if price is None or price <= 0:
            return

        shares = int(math.floor(B_ORDER_CASH / price))
        if shares > 0:
            algo.submit(self, shares, "B buy: AAPL red {0} days".format(state.red_streak))


class TwoSlotParallelTemplateAlgorithm(QCAlgorithm):
    """One template, two ungated slots running independently in parallel."""

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = []
        self.states = {}
        for ticker in TICKERS:
            equity = self.AddEquity(ticker, Resolution.Daily)
            self.symbols.append(equity.Symbol)
            self.states[equity.Symbol] = SymbolState()

        self.spy = self.symbols[0]
        self.aapl = self.symbols[1]

        # Indicators are updated manually, exactly once per daily bar, so that
        # "yesterday's value" is always available for cross detection.
        self.spy_sma = SimpleMovingAverage(SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(RSI_PERIOD, MovingAverageType.Wilders)
        self.sma_prev = None
        self.sma_now = None

        # Slot order: slot 1 then slot 2.
        self.strategies = [
            StrategyA(self, "Strategy A", self.spy),
            StrategyB(self, "Strategy B", self.aapl),
        ]

        # Lot bookkeeping for orders that are not filled synchronously.
        self._order_owner = {}
        self._order_pending = {}

        self.SetWarmUp(WARMUP_BARS, Resolution.Daily)

    # ------------------------------- rule helpers -------------------------------

    def spy_crossed_above_sma(self):
        state = self.states[self.spy]
        if self.sma_prev is None or self.sma_now is None or state.prev_close is None:
            return False
        return state.prev_close <= self.sma_prev and state.close > self.sma_now

    def spy_crossed_below_sma(self):
        state = self.states[self.spy]
        if self.sma_prev is None or self.sma_now is None or state.prev_close is None:
            return False
        return state.prev_close >= self.sma_prev and state.close < self.sma_now

    def _rules_ready(self):
        """No trading until every indicator / rolling window is fully formed."""
        if not self.spy_sma.IsReady or self.sma_prev is None or self.sma_now is None:
            return False
        if not self.aapl_rsi.IsReady:
            return False
        if self.states[self.spy].prev_close is None:
            return False
        # 3 consecutive red days need at least 4 closes for AAPL.
        if self.states[self.aapl].bar_count <= RED_DAYS_REQUIRED:
            return False
        return True

    # ---------------------------------- engine ----------------------------------

    def OnData(self, data):
        all_present = True

        # Market state is always computed from data, whether or not rules are evaluated.
        for symbol in self.symbols:
            bar = data.Bars[symbol] if data.Bars.ContainsKey(symbol) else None
            if bar is None:
                all_present = False
                continue

            if symbol == self.spy:
                self.sma_prev = float(self.spy_sma.Current.Value) if self.spy_sma.IsReady else None

            self.states[symbol].update(bar)

            if symbol == self.spy:
                self.spy_sma.Update(bar.EndTime, bar.Close)
                self.sma_now = float(self.spy_sma.Current.Value) if self.spy_sma.IsReady else None
            elif symbol == self.aapl:
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

        # A bar missing for ANY subscribed ticker skips all rule evaluation for the day.
        if not all_present:
            return

        if self.IsWarmingUp or not self._rules_ready():
            return

        # Sells are evaluated before buys.
        for strategy in self.strategies:
            strategy.evaluate_sell()
        for strategy in self.strategies:
            strategy.evaluate_buy()

    # ------------------------------ lot accounting ------------------------------

    def submit(self, strategy, quantity, tag):
        quantity = int(quantity)
        if quantity == 0:
            return

        ticket = self.MarketOrder(strategy.symbol, quantity, False, tag)
        if ticket is None:
            return

        filled = float(ticket.QuantityFilled)
        strategy.lot.shares += filled
        if abs(strategy.lot.shares) < EPS:
            strategy.lot.shares = 0.0

        remaining = quantity - filled
        if ticket.Status in TERMINAL_STATUSES or abs(remaining) < EPS:
            return

        strategy.lot.pending += remaining
        self._order_owner[ticket.OrderId] = strategy
        self._order_pending[ticket.OrderId] = remaining

    def OnOrderEvent(self, order_event):
        strategy = self._order_owner.get(order_event.OrderId, None)
        if strategy is None:
            return

        fill_quantity = float(order_event.FillQuantity)
        if abs(fill_quantity) > EPS:
            strategy.lot.shares += fill_quantity
            strategy.lot.pending -= fill_quantity
            self._order_pending[order_event.OrderId] -= fill_quantity
            if abs(strategy.lot.shares) < EPS:
                strategy.lot.shares = 0.0

        if order_event.Status in TERMINAL_STATUSES:
            leftover = self._order_pending.pop(order_event.OrderId, 0.0)
            strategy.lot.pending -= leftover
            if abs(strategy.lot.pending) < EPS:
                strategy.lot.pending = 0.0
            self._order_owner.pop(order_event.OrderId, None)
