# region imports
from AlgorithmImports import *
import math
# endregion


class SymbolState:
    """
    Per-ticker market state.

    Updated on every bar that arrives for the ticker, unconditionally: market
    state quantities (streaks, indicator values, previous closes) are always
    computed continuously from data, independent of any rule evaluation.
    """

    def __init__(self, symbol):
        self.symbol = symbol
        self.open = None
        self.close = None
        self.previous_close = None
        self.red_streak = 0
        self.green_streak = 0
        self._indicators = {}
        self._values = {}
        self._previous_values = {}

    def add_indicator(self, name, indicator):
        # Indicators are driven by hand (see update) rather than registered with
        # the engine, so a rule always reads a value that already includes the
        # bar currently being evaluated.
        self._indicators[name] = indicator
        self._values[name] = None
        self._previous_values[name] = None

    def update(self, bar):
        self.previous_close = self.close
        self.open = bar.open
        self.close = bar.close

        if self.previous_close is not None:
            if self.close < self.previous_close:        # red day
                self.red_streak += 1
                self.green_streak = 0
            elif self.close > self.previous_close:      # green day
                self.green_streak += 1
                self.red_streak = 0
            else:                                       # unchanged: neither
                self.red_streak = 0
                self.green_streak = 0

        for name, indicator in self._indicators.items():
            indicator.update(bar.end_time, bar.close)
            self._previous_values[name] = self._values[name]
            self._values[name] = float(indicator.current.value) if indicator.is_ready else None

    def value(self, name):
        return self._values[name]

    def previous_value(self, name):
        return self._previous_values[name]

    def indicator_formed(self, name):
        return self._values[name] is not None and self._previous_values[name] is not None


class Lot:
    """
    A strategy's private lot of shares: it only ever sells what it bought.

    Share count is booked optimistically at submission and reconciled from order
    events, so a rejected or partially filled order cannot leave the lot with a
    phantom position.
    """

    def __init__(self, algorithm, symbol, owner_name):
        self.algorithm = algorithm
        self.symbol = symbol
        self.owner_name = owner_name
        self.shares = 0
        self._pending = {}          # order id -> signed quantity still unfilled

    @property
    def is_open(self):
        return self.shares > 0

    def buy(self, quantity):
        quantity = int(math.floor(quantity))
        if quantity <= 0:
            return
        self._submit(quantity, f"{self.owner_name} buy")

    def sell(self, quantity):
        quantity = min(int(math.floor(quantity)), self.shares)
        if quantity <= 0:
            return
        self._submit(-quantity, f"{self.owner_name} sell")

    def liquidate(self):
        self.sell(self.shares)

    def _submit(self, signed_quantity, tag):
        ticket = self.algorithm.market_order(self.symbol, signed_quantity, tag=tag)
        self.shares += signed_quantity
        self._pending[ticket.order_id] = signed_quantity

    def on_order_event(self, order_event):
        order_id = order_event.order_id
        if order_id not in self._pending:
            return
        fill = int(order_event.fill_quantity)
        if fill != 0:
            self._pending[order_id] -= fill
        if order_event.status == OrderStatus.FILLED:
            self.shares -= self._pending.pop(order_id)      # drop unfilled residual
        elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
            self.shares -= self._pending.pop(order_id)      # roll the whole thing back


class Strategy:
    """One slot: a buy reason/details pair and a sell reason/details pair over a private lot."""

    def __init__(self, algorithm, name, symbol, buy_reason, buy_details, sell_reason, sell_details):
        self.name = name
        self.lot = Lot(algorithm, symbol, name)
        self._buy_reason = buy_reason
        self._buy_details = buy_details
        self._sell_reason = sell_reason
        self._sell_details = sell_details

    def evaluate_sell(self):
        # Sell reason is only evaluated while the lot is non-empty.
        if self.lot.is_open and self._sell_reason():
            self._sell_details(self.lot)

    def evaluate_buy(self):
        # Buy reason is only evaluated while the lot is empty.
        if not self.lot.is_open and self._buy_reason():
            self._buy_details(self.lot)


class ParallelTemplate:
    """Template with no gate: every slot is always allowed to act, independently."""

    def __init__(self, slots):
        self.slots = slots

    def evaluate(self):
        for slot in self.slots:         # sells before buys, across the whole template
            slot.evaluate_sell()
        for slot in self.slots:
            slot.evaluate_buy()

    def on_order_event(self, order_event):
        for slot in self.slots:
            slot.lot.on_order_event(order_event)


class TwoSlotParallelTemplateAlgorithm(QCAlgorithm):

    TICKERS = ["SPY", "AAPL", "IBM", "BAC", "AIG"]

    # Strategy A. The specification says "its simple moving average" without
    # naming a length; 20 daily bars is the default used here.
    SMA_PERIOD = 20
    A_ALLOCATION = 0.40

    # Strategy B.
    B_RED_DAYS = 3
    B_CASH_PER_TRADE = 20000.0
    RSI_PERIOD = 14
    RSI_EXIT_LEVEL = 60.0

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = []
        self.states = {}
        for ticker in self.TICKERS:
            symbol = self.add_equity(ticker, Resolution.DAILY).symbol
            self.symbols.append(symbol)
            self.states[symbol] = SymbolState(symbol)

        self.spy = self.symbols[0]
        self.aapl = self.symbols[1]

        self.states[self.spy].add_indicator("sma", SimpleMovingAverage(self.SMA_PERIOD))
        self.states[self.aapl].add_indicator(
            "rsi", RelativeStrengthIndex(self.RSI_PERIOD, MovingAverageType.WILDERS))

        self.template = ParallelTemplate([
            Strategy(self, "Strategy A", self.spy,
                     self._a_buy_reason, self._a_buy_details,
                     self._a_sell_reason, self._a_sell_details),
            Strategy(self, "Strategy B", self.aapl,
                     self._b_buy_reason, self._b_buy_details,
                     self._b_sell_reason, self._b_sell_details),
        ])

        self.set_warm_up(max(self.SMA_PERIOD, self.RSI_PERIOD) + 5, Resolution.DAILY)

    # ------------------------------------------------------------------ bars

    def on_data(self, data):
        bar_count = 0
        for symbol in self.symbols:
            bar = self._bar_for(data, symbol)
            if bar is not None:
                bar_count += 1
                self.states[symbol].update(bar)

        if self.is_warming_up:
            return

        # Today's bar missing for any subscribed ticker -> no rules run today.
        if bar_count < len(self.symbols):
