        if not self.lot.is_open or not self.is_formed():
            return
        if self.reason_to_sell():
            self.sell_details()

    def evaluate_buy(self):
        if self.lot.is_open or not self.is_formed():
            return
        if self.reason_to_buy():
            self.buy_details()

