class StrategyLot:
    """
    A private lot of shares owned by exactly one strategy.

    A lot only ever sells shares that it bought itself, so its buy reason is
    evaluated only while it is empty and its sell reason only while it is
    non-empty.  Quantity is accounted optimistically at submission time and
    reconciled from order events (an unfilled remainder on a canceled/invalid
    order is rolled back), so a reason can never fire twice for the same lot.
    """

    def __init__(self, algorithm, symbol, name):
        self._algorithm = algorithm
        self._pending = {}          # order id -> signed quantity not yet filled
        self.symbol = symbol
        self.name = name
        self.quantity = 0           # shares currently owned by this lot

    @property
    def is_empty(self):
        return self.quantity <= 0

    @property
    def is_open(self):
        return self.quantity > 0

    def buy(self, quantity):
        quantity = int(quantity)
        if quantity <= 0:
            return
        self._submit(quantity, "buy")

    def sell(self, quantity):
        quantity = min(int(quantity), self.quantity)
        if quantity <= 0:
            return
        self._submit(-quantity, "sell")

    def liquidate(self):
