        if ticket is None or ticket.Status == OrderStatus.Invalid:
            return False
        self.shares += delta
        self.algorithm.order_intents[ticket.OrderId] = {"lot": self, "delta": delta, "filled": 0}
        return True


class TwoSlotParallelTemplateAlgorithm(QCAlgorithm):
    """
    One template, 2 slots, no gate. Both slots run independently in parallel.

    Slot 1 - Strategy A (SPY)
        buy : SPY close crosses above its 100-day SMA -> invest 40% of total portfolio value
        sell: SPY close crosses below its 100-day SMA -> liquidate Strategy A's lot

    Slot 2 - Strategy B (AAPL)
        buy : AAPL red 3 consecutive days -> buy $20,000 of AAPL if >= $20,000 cash is available
        sell: AAPL 14-day RSI closes above 60 -> liquidate Strategy B's lot
    """

    # ----------------------------------------------------------------- setup
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            equity = self.AddEquity(ticker, Resolution.Daily)
            equity.SetDataNormalizationMode(DataNormalizationMode.Adjusted)
            self.symbols[ticker] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # ---- market state: always computed from data, never paused ----
        self.prev_close = {symbol: None for symbol in self.symbols.values()}
        self.bar_count = {symbol: 0 for symbol in self.symbols.values()}

        # indicators are updated manually so the ordering
        # (read yesterday's value -> fold in today's close -> read today's value)
        # is explicit and deterministic
        self.spy_sma = SimpleMovingAverage(100)
        self.spy_close_today = None
        self.spy_close_yday = None
        self.spy_sma_today = None
        self.spy_sma_yday = None

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_close_today = None
        self.aapl_red_streak = 0          # consecutive red days completed as of today

        # ---- private lots, one per strategy ----
        self.order_intents = {}
        self.lot_a = StrategyLot(self, "A", self.spy)
        self.lot_b = StrategyLot(self, "B", self.aapl)

        # nothing trades until every indicator / rolling window is fully formed
        self.SetWarmUp(150, Resolution.Daily)

    # ------------------------------------------------------------ daily loop
    def OnData(self, data):
        # 1) market state first: it is computed continuously from whatever data arrives
        self.UpdateMarketState(data)

        if self.IsWarmingUp:
            return

        # 2) if today's bar is missing for ANY subscribed ticker, skip all rule evaluation
        if not self.AllTickersHaveBars(data):
            return

        # 3) sells before buys, slot order 1 then 2
        self.StrategyASell()
        self.StrategyBSell()
        self.StrategyABuy()
        self.StrategyBBuy()

    def UpdateMarketState(self, data):
        for symbol in self.symbols.values():
            bar = self.GetBar(data, symbol)
            if bar is None:
                continue

            close = bar.Close
            previous = self.prev_close[symbol]

            if symbol == self.spy:
                self.spy_sma_yday = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
                self.spy_sma.Update(bar.EndTime, close)
                self.spy_sma_today = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
                self.spy_close_yday = previous
                self.spy_close_today = close

            elif symbol == self.aapl:
                self.aapl_rsi.Update(bar.EndTime, close)
                if previous is not None:
                    # red day = close strictly below the previous day's close
                    self.aapl_red_streak = (self.aapl_red_streak + 1) if close < previous else 0
                self.aapl_close_today = close

            self.prev_close[symbol] = close
            self.bar_count[symbol] += 1

    # ------------------------------------------------- slot 1 : strategy A
    def StrategyAReady(self):
        return (self.spy_sma.IsReady
                and self.spy_sma_today is not None
                and self.spy_sma_yday is not None
                and self.spy_close_today is not None
                and self.spy_close_yday is not None)

    def StrategyASell(self):
        # sell reason is evaluated only while the lot is non-empty
        if self.lot_a.IsEmpty or not self.StrategyAReady():
            return
        crossed_below = (self.spy_close_yday >= self.spy_sma_yday
                         and self.spy_close_today < self.spy_sma_today)
        if crossed_below:
            self.lot_a.Liquidate("SPY close crossed below 100d SMA")

    def StrategyABuy(self):
        # buy reason is evaluated only while the lot is empty
        if not self.lot_a.IsEmpty or not self.StrategyAReady():
            return
        crossed_above = (self.spy_close_yday <= self.spy_sma_yday
                         and self.spy_close_today > self.spy_sma_today)
        if not crossed_above:
            return
        target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
        quantity = int(math.floor(target_value / self.spy_close_today))
        if quantity > 0:
            self.lot_a.Buy(quantity, "SPY close crossed above 100d SMA")

    # ------------------------------------------------- slot 2 : strategy B
    def StrategyBReady(self):
        return (self.aapl_rsi.IsReady
                and self.aapl_close_today is not None
                and self.bar_count[self.aapl] >= 4)

    def StrategyBSell(self):
        if self.lot_b.IsEmpty or not self.StrategyBReady():
            return
        if self.aapl_rsi.Current.Value > 60:
            self.lot_b.Liquidate("AAPL 14d RSI closed above 60")

    def StrategyBBuy(self):
        if not self.lot_b.IsEmpty or not self.StrategyBReady():
            return
        if self.aapl_red_streak < 3:
            return
        budget = 20000.0
        # not enough available cash -> do nothing this bar, stay flat
        if float(self.Portfolio.Cash) < budget:
            return
        quantity = int(math.floor(budget / self.aapl_close_today))
        if quantity > 0:
            self.lot_b.Buy(quantity, "AAPL red 3 consecutive days")

    # ----------------------------------------------------------- utilities
    def AllTickersHaveBars(self, data):
        for symbol in self.symbols.values():
            if self.GetBar(data, symbol) is None:
                return False
        return True

    def GetBar(self, data, symbol):
        if data is None or data.Bars is None:
            return None
        if not data.Bars.ContainsKey(symbol):
            return None
        bar = data.Bars[symbol]
        if bar is None or bar.Close <= 0:
            return None
        return bar

    def OnOrderEvent(self, orderEvent):
        intent = self.order_intents.get(orderEvent.OrderId)
        if intent is None:
            return

        status = orderEvent.Status
        if status in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
            intent["filled"] += int(orderEvent.FillQuantity)

        if status == OrderStatus.Filled:
            self.order_intents.pop(orderEvent.OrderId, None)
        elif status in (OrderStatus.Canceled, OrderStatus.Invalid):
            unfilled = int(intent["delta"]) - int(intent["filled"])
            intent["lot"].shares -= unfilled
            self.order_intents.pop(orderEvent.OrderId, None)
