        self._rsi = self.rsi(self._aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        # --- continuously maintained market state --------------------------
        # (never paused; updated from whatever data arrives, trading or not)
        self._prev_close = {symbol: None for symbol in self._symbols.values()}
        self._red_streak = {symbol: 0 for symbol in self._symbols.values()}
        self._prev_sma = None

