        self._lot = {self.SLOT_A: 0, self.SLOT_B: 0}
        self._pending = {self.SLOT_A: False, self.SLOT_B: False}
        self._order_owner = {}

        # enough history for SMA(100) / RSI(14) plus one prior bar for crosses
        self.set_warm_up(150, Resolution.DAILY)

    # ----------------------------------------------------------------------
    # daily bar handling
    # ----------------------------------------------------------------------
    def on_data(self, slice):
        # collect today's bars for every subscribed ticker
        bars = {}
        for symbol in self._symbols.values():
            if slice.bars.contains_key(symbol):
                bar = slice.bars[symbol]
                if bar is not None:
                    bars[symbol] = bar

        # market-state quantities are always computed from the data available
        closes = {}
        for symbol, bar in bars.items():
            close = bar.close
            closes[symbol] = close
            previous = self._prev_close[symbol]
            if previous is not None:
                # red day: close strictly below the previous close
                if close < previous:
                    self._red_streak[symbol] += 1
                else:
                    self._red_streak[symbol] = 0

