            if spy_prev_close >= spy_prev_sma and spy_close < spy_sma:
                self._submit(self.SLOT_A, self._spy, -self._lot[self.SLOT_A],
                             "A sell: SPY close crossed below SMA(100)")

        # Slot 2 - Strategy B: AAPL 14-day RSI closes above 60
        if self._can_sell(self.SLOT_B):
            if aapl_rsi > 60:
                self._submit(self.SLOT_B, self._aapl, -self._lot[self.SLOT_B],
                             "B sell: AAPL RSI(14) above 60")

        # ---------------- BUYS -----------------
        # Slot 1 - Strategy A: SPY close crosses above its 100-day SMA -> 40% of portfolio
        if self._can_buy(self.SLOT_A):
            if spy_prev_close <= spy_prev_sma and spy_close > spy_sma and spy_close > 0:
                target_value = 0.40 * self.portfolio.total_portfolio_value
                quantity = int(math.floor(target_value / spy_close))
                if quantity > 0:
                    self._submit(self.SLOT_A, self._spy, quantity,
                                 "A buy: SPY close crossed above SMA(100)")

        # Slot 2 - Strategy B: AAPL red 3 consecutive days -> $20,000 if cash allows
        if self._can_buy(self.SLOT_B):
            if self._red_streak[self._aapl] >= 3 and aapl_close > 0:
                available_cash = self.portfolio.cash_book[self.account_currency].amount
                if available_cash >= 20000:
                    quantity = int(math.floor(20000 / aapl_close))
                    if quantity > 0:
                        self._submit(self.SLOT_B, self._aapl, quantity,
                                     "B buy: AAPL red 3 consecutive days")

    # ----------------------------------------------------------------------
    # lot / order plumbing
    # ----------------------------------------------------------------------
    def _can_buy(self, slot):
        return self._lot[slot] == 0 and not self._pending[slot]

    def _can_sell(self, slot):
        return self._lot[slot] > 0 and not self._pending[slot]

    def _submit(self, slot, symbol, quantity, tag):
        if quantity == 0:
            return
        ticket = self.market_order(symbol, quantity, tag=tag)
        if ticket is None:
            return
        self._order_owner[ticket.order_id] = slot
        self._pending[slot] = True

    def on_order_event(self, order_event):
        slot = self._order_owner.get(order_event.order_id)
        if slot is None:
            return

        if order_event.status in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED):
            self._lot[slot] = max(0, self._lot[slot] + int(order_event.fill_quantity))

        if order_event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.INVALID):
            self._pending[slot] = False
            self._order_owner.pop(order_event.order_id, None)

