class SymbolMarketState:
    """
    Per-symbol market state. It is fed from every bar that arrives and is never
    paused by anything the strategies do.
    """

    def __init__(self):
        self.close = None        # today's close
        self.prev_close = None   # yesterday's close
        self.red_streak = 0      # consecutive closes strictly below the previous close
        self.green_streak = 0    # consecutive closes strictly above the previous close

    def update(self, bar):
        close = float(bar.Close)
        if self.close is not None:
            if close < self.close:
                self.red_streak += 1
                self.green_streak = 0
            elif close > self.close:
                self.green_streak += 1
                self.red_streak = 0
            else:
                # an unchanged close is neither red nor green: it breaks both streaks
                self.red_streak = 0
                self.green_streak = 0
        self.prev_close = self.close
        self.close = close


class Lot:
    """
    A strategy's private inventory. A strategy may only sell shares it bought
    itself, so every fill is booked against the lot that submitted the order.
    """

    CLOSED_STATES = (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid)
    FILL_STATES = (OrderStatus.Filled, OrderStatus.PartiallyFilled)

    def __init__(self, algorithm, name, symbol):
        self.algorithm = algorithm
        self.name = name
        self.symbol = symbol
        self.shares = 0
        self.pending_ids = set()

    @property
    def is_empty(self):
        # a lot with work in flight is not available for a fresh buy reason
        return self.shares == 0 and len(self.pending_ids) == 0

    def buy(self, quantity, reason):
        quantity = int(quantity)
        if quantity <= 0:
            return
        tag = "{0} BUY {1} {2} ({3})".format(self.name, quantity, self.symbol.Value, reason)
        ticket = self.algorithm.MarketOrder(self.symbol, quantity, False, tag)
        if ticket is not None:
            self.pending_ids.add(ticket.OrderId)
        self.algorithm.Log(tag)

    def sell(self, quantity, reason):
        quantity = int(min(int(quantity), self.shares))
        if quantity <= 0:
            return
        tag = "{0} SELL {1} {2} ({3})".format(self.name, quantity, self.symbol.Value, reason)
        ticket = self.algorithm.MarketOrder(self.symbol, -quantity, False, tag)
        if ticket is not None:
            self.pending_ids.add(ticket.OrderId)
        self.algorithm.Log(tag)

    def liquidate(self, reason):
        self.sell(self.shares, reason)

    def handle_order_event(self, order_event):
        if order_event.OrderId not in self.pending_ids:
            return False
        if order_event.Status in self.FILL_STATES:
            self.shares += int(round(float(order_event.FillQuantity)))
            if self.shares < 0:
                self.shares = 0
        if order_event.Status in self.CLOSED_STATES:
            self.pending_ids.discard(order_event.OrderId)
        return True


